<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useMarketStore} from '../store'
import {usePolling} from '../usePolling'
import {api} from '../api'
import {compareNullable,number,percent,time,title} from '../format'
import FeatureValue from '../components/FeatureValue.vue'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
import Pager from '../components/Pager.vue'
import CapitalDetail from '../components/CapitalDetail.vue'
const store=useMarketStore(); const search=ref(''); const deepOnly=ref(false); const page=ref(0); const selectedId=ref<number|null>(null)
const raw=ref<{coverageStart:string|null;lastStreamActivity:string|null}|null>(null)
const {error}=usePolling(async signal=>{await store.refresh(signal); if(selectedId.value!==null) raw.value=await api(`/api/assets/${selectedId.value}/derivatives?limit=100`,{signal})},5000)
const filtered=computed(()=>store.assets.filter(m=>m.instrument.symbol.toLowerCase().includes(search.value.trim().toLowerCase())&&(!deepOnly.value||m.features.derivatives.takerBuyShare.status===0)).sort((a,b)=>compareNullable(a.features.derivatives.openInterestUsd.value,b.features.derivatives.openInterestUsd.value,true)))
const paged=computed(()=>filtered.value.slice(page.value*30,(page.value+1)*30));const selected=computed(()=>store.assets.find(m=>m.instrument.assetId===selectedId.value));const d=computed(()=>selected.value?.features.derivatives)
watch([search,deepOnly],()=>{page.value=0});watch(selectedId,()=>{raw.value=null})
const cooldown=computed(()=>store.health.find(h=>h.health.name==='Binance Cooldown')?.health.error)
</script>
<template><PageIntro eyebrow="BINANCE FUTURES · DERIVATIVES" title="价格背后，仓位正在变化。" description="全市场 OI 轮询，候选池按需加载持仓比与主动买卖数据。"><span class="live-pill">{{time(store.updatedAt)}}</span></PageIntro><p v-if="error" class="radar-notice" role="alert">{{error}} 缓存字段请核对源时间。</p><p class="radar-notice">OI 变化按数量计算。Top Account 与 Top Position 不能混用；Taker 使用已完成周期。强平为交易所抽样快照，预热与断线时为 Unknown。</p><p v-if="cooldown" class="radar-notice">{{cooldown}}</p><div class="stats"><StatCard label="监控合约" :value="store.assets.length" foot="USDT 永续 · 活跃合约"/><StatCard label="有效 OI" :value="store.assets.filter(m=>m.features.derivatives.openInterestQuantity.status===0).length" foot="保留字段源时间"/><StatCard label="有效 Taker" :value="store.assets.filter(m=>m.features.derivatives.takerBuyShare.status===0).length" foot="候选分层采集 · 5m 已完成周期"/><StatCard label="OI 历史统计就绪" :value="store.assets.filter(m=>m.features.derivatives.oiRobustZ.status===0).length" foot="至少 30 个基线样本 · MAD 非零"/></div><div class="section-heading"><h2>资金结构总览</h2><span class="refresh-text">默认 5 分钟采集 · 页面每 5 秒读取</span></div><div class="market-panel"><div class="toolbar"><label class="search"><input v-model="search" aria-label="搜索衍生品合约" placeholder="搜索 ARIA、BTC 等合约"></label><label class="checkbox"><input v-model="deepOnly" type="checkbox">仅深度数据可用</label><span class="results">{{filtered.length}} 个结果</span></div><div class="table-scroll"><table><thead><tr><th>合约</th><th>OI 数量</th><th>OI 美元值</th><th>OI 15m</th><th>OI RZ</th><th>Taker 买量占比</th><th>Global 多头占比</th><th>Top Position 多头</th><th>Price / OI</th></tr></thead><tbody><tr v-for="m in paged" :key="m.instrument.assetId" @click="selectedId=m.instrument.assetId"><td>{{m.instrument.symbol}}</td><td><FeatureValue :feature="m.features.derivatives.openInterestQuantity"/></td><td><FeatureValue :feature="m.features.derivatives.openInterestUsd"/></td><td><FeatureValue :feature="m.features.derivatives.oiChanges[15]" suffix="%"/></td><td><FeatureValue :feature="m.features.derivatives.oiRobustZ"/></td><td><FeatureValue :feature="m.features.derivatives.takerBuyShare" :multiplier="100" suffix="%"/></td><td><FeatureValue :feature="m.features.derivatives.globalLongShare" :multiplier="100" suffix="%"/></td><td><FeatureValue :feature="m.features.derivatives.topPositionLongShare" :multiplier="100" suffix="%"/></td><td>{{m.features.derivatives.priceOiStructure}}</td></tr><tr v-if="!filtered.length"><td colspan="9" class="empty">等待采集或没有符合条件的合约。缺失数据不会用 0 填充。</td></tr></tbody></table></div><Pager v-model="page" :total="filtered.length">点击合约查看源时间、账户与强平观测。</Pager></div>
<section v-if="selected&&d" class="detail"><div class="section-heading"><h2>{{selected.instrument.symbol}} · 衍生品详情</h2><button class="text-button" @click="selectedId=null">收起 ×</button></div><div class="detail-grid"><div><span>Top Account 多头占比</span><strong><FeatureValue :feature="d.topAccountLongShare" :multiplier="100" suffix="%"/></strong></div><div><span>Top Position 15m 变化</span><strong><FeatureValue :feature="d.topPositionChange15m" suffix=" pp"/></strong></div><div><span>Taker 买卖比</span><strong><FeatureValue :feature="d.takerBuySellRatio"/></strong></div><div><span>OI 基线样本</span><strong>{{d.oiBaselineSamples}}</strong></div><div><span>观测多头强平 · 15m USD</span><strong><FeatureValue :feature="d.observedLongLiquidation15mUsd"/></strong></div><div><span>观测空头强平 · 15m USD</span><strong><FeatureValue :feature="d.observedShortLiquidation15mUsd"/></strong></div><div><span>连续覆盖 15m</span><strong>{{d.liquidationCoverageComplete?'已覆盖':'预热中 / 连接中断'}}</strong></div><div><span>Funding</span><strong>{{percent(selected.fundingRate==null?null:selected.fundingRate*100)}}</strong></div></div><p>{{d.liquidationCaveat}}</p><p>OI：{{title(d.openInterestQuantity)}}；Taker：{{title(d.takerBuyShare)}}</p><p v-if="raw">流覆盖开始 {{time(raw.coverageStart,true)}} · 最近活动 {{time(raw.lastStreamActivity,true)}}</p></section><CapitalDetail v-if="selected" :market="selected" /></template>
